# ZCode app icon restore (v1, portable) - save as UTF-8 WITHOUT BOM
# - Puts back the icon files this machine had before patch-zcode-icon.ps1 ran:
#     * resources\tray_icon.ico / icon_windows.png / icon.png
#       <- app-icon-backup\ (snapshot of the first run)
#     * if that backup is gone: rebuilt from icon\app-icon-original.ico (the
#       factory baseline generated by the patch script). resources\icon.png is
#       NOT used as a baseline because the patch overwrites it.
# - Shortcuts: reads zcode-icon-state.json and reverts IconLocation only when the
#   current value is still the one the patch wrote (manual edits are left alone).
# - ZCode.exe is never modified, so there is nothing else to undo.
param(
    [switch]$NoRestart,   # toolbox mode: do not relaunch ZCode after restoring
    [switch]$Factory,     # ignore app-icon-backup and always rebuild from the factory baseline
    [string]$TargetDir    # advanced/testing: operate on a COPY of the resources dir
)
$ErrorActionPreference = 'Stop'
try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch {}
try { Remove-Item Env:NODE_OPTIONS -ErrorAction SilentlyContinue } catch {}
Add-Type -AssemblyName System.Drawing

$backupDir  = Join-Path $PSScriptRoot 'app-icon-backup'
$statePath  = Join-Path $PSScriptRoot 'zcode-icon-state.json'
$iconDir  = Join-Path $PSScriptRoot 'icon'
$factoryIco = Join-Path $iconDir 'app-icon-original.ico'

# ---- icon encoding helpers (same primitives as the patch script) -------------------
function Resize-Bitmap([System.Drawing.Bitmap]$src, [int]$w, [int]$h) {
    $bmp = New-Object System.Drawing.Bitmap($w, $h, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    try {
        $g.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $g.PixelOffsetMode   = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $g.SmoothingMode     = [System.Drawing.Drawing2D.SmoothingMode]::HighQuality
        $g.CompositingMode   = [System.Drawing.Drawing2D.CompositingMode]::SourceCopy
        $g.Clear([System.Drawing.Color]::Transparent)
        $g.DrawImage($src, (New-Object System.Drawing.Rectangle(0, 0, $w, $h)))
    } finally { $g.Dispose() }
    return $bmp
}
function ConvertTo-DibFrame([System.Drawing.Bitmap]$bmp) {
    $w = $bmp.Width
    $h = $bmp.Height
    $rect = New-Object System.Drawing.Rectangle(0, 0, $w, $h)
    $data = $bmp.LockBits($rect, [System.Drawing.Imaging.ImageLockMode]::ReadOnly, [System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
    try {
        $stride = $data.Stride
        $buf = New-Object byte[] ($stride * $h)
        [System.Runtime.InteropServices.Marshal]::Copy($data.Scan0, $buf, 0, $buf.Length)
    } finally { $bmp.UnlockBits($data) }
    $ms = New-Object System.IO.MemoryStream
    $bw = New-Object System.IO.BinaryWriter($ms)
    try {
        $bw.Write([uint32]40); $bw.Write([int32]$w); $bw.Write([int32]($h * 2))
        $bw.Write([uint16]1); $bw.Write([uint16]32); $bw.Write([uint32]0)
        $bw.Write([uint32]($w * $h * 4)); $bw.Write([int32]0); $bw.Write([int32]0)
        $bw.Write([uint32]0); $bw.Write([uint32]0)
        for ($y = $h - 1; $y -ge 0; $y--) { $bw.Write($buf, $y * $stride, $w * 4) }
        $maskRow = [int]([Math]::Ceiling($w / 32.0) * 4)
        $bw.Write((New-Object byte[] ($maskRow * $h)))
        $bw.Flush()
        return $ms.ToArray()
    } finally { $bw.Dispose(); $ms.Dispose() }
}
function ConvertTo-PngFrame([System.Drawing.Bitmap]$bmp) {
    $ms = New-Object System.IO.MemoryStream
    try { $bmp.Save($ms, [System.Drawing.Imaging.ImageFormat]::Png); return $ms.ToArray() } finally { $ms.Dispose() }
}
function New-IcoBytes([System.Drawing.Bitmap]$src) {
    $sizes = @(16, 20, 24, 32, 40, 48, 64, 128, 256)
    $frames = New-Object System.Collections.ArrayList
    foreach ($s in $sizes) {
        if ($s -gt $src.Width) { continue }
        $b = Resize-Bitmap $src $s $s
        try {
            if ($s -le 128) { $data = ConvertTo-DibFrame $b } else { $data = ConvertTo-PngFrame $b }
        } finally { $b.Dispose() }
        [void]$frames.Add(@{ size = $s; data = $data })
    }
    if ($frames.Count -eq 0) { throw 'source icon too small (need at least 16x16).' }
    $count = $frames.Count
    $ms = New-Object System.IO.MemoryStream
    $bw = New-Object System.IO.BinaryWriter($ms)
    try {
        $bw.Write([uint16]0); $bw.Write([uint16]1); $bw.Write([uint16]$count)
        $offset = 6 + 16 * $count
        foreach ($f in $frames) {
            $dim = if ($f.size -ge 256) { 0 } else { $f.size }
            $bw.Write([byte]$dim); $bw.Write([byte]$dim); $bw.Write([byte]0); $bw.Write([byte]0)
            $bw.Write([uint16]1); $bw.Write([uint16]32)
            $bw.Write([uint32]$f.data.Length); $bw.Write([uint32]$offset)
            $offset += $f.data.Length
        }
        foreach ($f in $frames) { $bw.Write([byte[]]$f.data) }
        $bw.Flush()
        return $ms.ToArray()
    } finally { $bw.Dispose(); $ms.Dispose() }
}
function Load-SourceBitmap([string]$path) {
    $ext = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    if ($ext -ne '.ico') {
        $img = [System.Drawing.Image]::FromFile($path)
        try { return (New-Object System.Drawing.Bitmap($img)) } finally { $img.Dispose() }
    }
    # ico: GDI+ defaults to 32x32 for multi-frame files and cannot decode
    # PNG-compressed frames at all, so parse the header, ask for the LARGEST
    # frame, and fall back to the embedded PNG when GDI+ refuses.
    $bytes = [System.IO.File]::ReadAllBytes($path)
    $count = [BitConverter]::ToUInt16($bytes, 4)
    $bestW = 0; $bestH = 0; $best = $null
    for ($i = 0; $i -lt $count; $i++) {
        $o = 6 + 16 * $i
        $w = [int]$bytes[$o]; if ($w -eq 0) { $w = 256 }
        $h = [int]$bytes[$o + 1]; if ($h -eq 0) { $h = 256 }
        if ($w * $h -gt $bestW * $bestH) { $bestW = $w; $bestH = $h }
        $len = [int][BitConverter]::ToUInt32($bytes, $o + 8)
        $off = [int][BitConverter]::ToUInt32($bytes, $o + 12)
        if ($off + $len -gt $bytes.Length) { continue }
        $magic = ($bytes[$off] -eq 0x89 -and $bytes[$off + 1] -eq 0x50 -and $bytes[$off + 2] -eq 0x4E -and $bytes[$off + 3] -eq 0x47)
        if ($magic -and ($null -eq $best -or $len -gt $best.len)) { $best = @{ off = $off; len = $len; w = $w; h = $h } }
    }
    # the largest frame is often the PNG one; GDI+ silently returns a smaller
    # DIB frame in that case, so decode the PNG directly when it is the biggest
    if ($best -and $best.w -eq $bestW -and $best.h -eq $bestH) {
        $ms0 = New-Object System.IO.MemoryStream(,$bytes[$best.off..($best.off + $best.len - 1)])
        $img0 = [System.Drawing.Image]::FromStream($ms0)
        try { return (New-Object System.Drawing.Bitmap($img0)) } finally { $img0.Dispose(); $ms0.Dispose() }
    }
    if ($bestW -gt 0) {
        try {
            $ico = New-Object System.Drawing.Icon($path, $bestW, $bestH)
            try {
                $bmp = $ico.ToBitmap()
                $copy = New-Object System.Drawing.Bitmap($bmp)
                $bmp.Dispose()
                return $copy
            } finally { $ico.Dispose() }
        } catch {}
    }
    if (-not $best) { throw 'this .ico has no readable frame; pass a .png instead.' }
    $ms = New-Object System.IO.MemoryStream(,$bytes[$best.off..($best.off + $best.len - 1)])
    $img = [System.Drawing.Image]::FromStream($ms)
    try { return (New-Object System.Drawing.Bitmap($img)) } finally { $img.Dispose(); $ms.Dispose() }
}

function Find-ZCodeDir {
    try {
        $p = Get-Process -Name 'ZCode' -ErrorAction SilentlyContinue | Where-Object Path | Select-Object -First 1
        if ($p) {
            $cand = Join-Path (Split-Path $p.Path -Parent) 'resources\app.asar'
            if (Test-Path $cand) { return (Split-Path $cand -Parent) }
        }
    } catch {}
    $keys = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*',
              'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*',
              'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*')
    foreach ($k in $keys) {
        try {
            $hit = Get-ItemProperty $k -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -like '*ZCode*' -and $_.InstallLocation } | Select-Object -First 1
            if ($hit) {
                $cand = Join-Path $hit.InstallLocation 'resources\app.asar'
                if (Test-Path $cand) { return (Split-Path $cand -Parent) }
            }
        } catch {}
    }
    $candidates = @('D:\installer\zcode', "$env:LOCALAPPDATA\Programs\zcode", "$env:ProgramFiles\zcode", "${env:ProgramFiles(x86)}\zcode")
    foreach ($d in $candidates) {
        try {
            if (-not (Test-Path $d)) { continue }
            $cand = Join-Path $d 'resources\app.asar'
            if (Test-Path $cand) { return (Split-Path $cand -Parent) }
        } catch { continue }
    }
    return $null
}
function Invoke-ShellIconRefresh {
    foreach ($cmd in @(@('ie4uinit.exe', '-show'), @('ie4uinit.exe', '-ClearIconCache'))) {
        try { Start-Process -FilePath $cmd[0] -ArgumentList $cmd[1] -Wait -WindowStyle Hidden -ErrorAction SilentlyContinue } catch {}
    }
}

# ================= main =================
if ($TargetDir) {
    $resourcesDir = $TargetDir
    $zcodeExe = $null
} else {
    $resourcesDir = Find-ZCodeDir
    if (-not $resourcesDir) {
        Write-Host '[?] Could not auto-locate ZCode. Example: D:\installer\zcode\resources' -ForegroundColor Yellow
        $manual = Read-Host 'Enter the resources folder (the one containing app.asar)'
        if (-not $manual -or -not (Test-Path (Join-Path $manual 'app.asar'))) {
            Write-Host "[X] app.asar not found under: $manual" -ForegroundColor Red
            Read-Host 'Press Enter to exit'
            exit 1
        }
        $resourcesDir = $manual
    }
    $zcodeExe = Join-Path (Split-Path $resourcesDir -Parent) 'ZCode.exe'
    if (-not (Test-Path $zcodeExe)) { $zcodeExe = $null }
    if (Get-Process -Name 'ZCode' -ErrorAction SilentlyContinue) {
        Write-Host '[X] ZCode is running.' -ForegroundColor Red
        Write-Host '    Quit ZCode first (right-click tray icon -> Quit).' -ForegroundColor Yellow
        Read-Host 'Press Enter to exit'
        exit 1
    }
}
Write-Host "target: $resourcesDir"

# 1) tray icon
$trayPath = Join-Path $resourcesDir 'tray_icon.ico'
$backupTray = Join-Path $backupDir 'tray_icon.ico'
if ((-not $Factory) -and (Test-Path -LiteralPath $backupTray)) {
    Copy-Item -LiteralPath $backupTray -Destination $trayPath -Force
    Write-Host '[1/5] tray_icon.ico restored from app-icon-backup'
} else {
    # resources\icon.png is NOT a valid baseline here: the patch overwrites it.
    if (-not (Test-Path -LiteralPath $factoryIco)) {
        throw 'no backup and no factory baseline (icon\app-icon-original.ico). Reinstall ZCode or restore its icons, then run patch-zcode-icon.ps1 once to rebuild the baseline.'
    }
    Write-Host '[1/5] backup missing: rebuilding from icon\app-icon-original.ico'
    $fb = Load-SourceBitmap $factoryIco
    try { [System.IO.File]::WriteAllBytes("$trayPath.tmp", (New-IcoBytes $fb)) } finally { $fb.Dispose() }
    Move-Item -Force "$trayPath.tmp" $trayPath
}

# 2) window icon
$winPath = Join-Path $resourcesDir 'icon_windows.png'
$backupWin = Join-Path $backupDir 'icon_windows.png'
if ((-not $Factory) -and (Test-Path -LiteralPath $backupWin)) {
    Copy-Item -LiteralPath $backupWin -Destination $winPath -Force
    Write-Host '[2/5] icon_windows.png restored from app-icon-backup'
} else {
    if (-not (Test-Path -LiteralPath $factoryIco)) {
        throw 'no backup and no factory baseline (icon\app-icon-original.ico). Reinstall ZCode or restore its icon.png, then run patch-zcode-icon.ps1 once to rebuild the baseline.'
    }
    $fb = Load-SourceBitmap $factoryIco
    try {
        $size = [Math]::Min(512, $fb.Width)
        $out = Resize-Bitmap $fb $size $size
        try { $out.Save("$winPath.tmp", [System.Drawing.Imaging.ImageFormat]::Png) } finally { $out.Dispose() }
    } finally { $fb.Dispose() }
    Move-Item -Force "$winPath.tmp" $winPath
    Write-Host '[2/5] icon_windows.png rebuilt from the factory baseline'
}

# 3) app icon png (About window + drag helper); rebuilt at the factory 1024 when
#    no backup exists, because the patch overwrote the original icon.png
$appPngPath = Join-Path $resourcesDir 'icon.png'
$backupApp = Join-Path $backupDir 'icon.png'
if ((-not $Factory) -and (Test-Path -LiteralPath $backupApp)) {
    Copy-Item -LiteralPath $backupApp -Destination $appPngPath -Force
    Write-Host '[3/5] icon.png restored from app-icon-backup'
} else {
    if (-not (Test-Path -LiteralPath $factoryIco)) {
        throw 'no backup and no factory baseline (icon\app-icon-original.ico) for icon.png. Refusing.'
    }
    $fb = Load-SourceBitmap $factoryIco
    try {
        $size = [Math]::Min(1024, $fb.Width)
        $out = Resize-Bitmap $fb $size $size
        try { $out.Save("$appPngPath.tmp", [System.Drawing.Imaging.ImageFormat]::Png) } finally { $out.Dispose() }
    } finally { $fb.Dispose() }
    Move-Item -Force "$appPngPath.tmp" $appPngPath
    Write-Host '[3/5] icon.png rebuilt from the factory baseline'
}

# 4) shortcuts (only when they still carry the value this patch wrote)
$reverted = 0
if (Test-Path -LiteralPath $statePath) {
    try {
        $state = Get-Content -LiteralPath $statePath -Raw -Encoding UTF8 | ConvertFrom-Json
        $wsh = New-Object -ComObject WScript.Shell
        foreach ($rec in @($state.shortcuts)) {
            if (-not $rec -or -not $rec.path) { continue }
            if (-not (Test-Path -LiteralPath $rec.path)) { continue }
            try {
                $lnk = $wsh.CreateShortcut($rec.path)
                if ($lnk.IconLocation -ine $rec.applied) {
                    Write-Host "      skip (icon location changed manually): $($rec.path)" -ForegroundColor Yellow
                    continue
                }
                $lnk.IconLocation = $rec.original
                $lnk.Save()
                $reverted++
                Write-Host "      shortcut reverted: $($rec.path)"
            } catch {
                Write-Host "      [warn] shortcut not reverted (permission?): $($rec.path)" -ForegroundColor Yellow
            }
        }
    } catch {
        Write-Host '      [warn] state file unreadable; shortcuts left as-is' -ForegroundColor Yellow
    }
} else {
    Write-Host '      no state file: shortcuts left as-is'
}
Write-Host "[4/5] shortcuts reverted: $reverted"
if (-not $TargetDir) { Invoke-ShellIconRefresh }
Write-Host '[5/5] done'

if ($NoRestart) {
    Write-Host 'done (NoRestart: leave ZCode closed).'
} elseif ($zcodeExe -and (Test-Path -LiteralPath $zcodeExe)) {
    Start-Process $zcodeExe
    Write-Host 'ZCode restarted.'
} else {
    Write-Host 'done. Start ZCode manually.'
}
